/* HTML */
(() => { 
    const title = document.title;
    const url = document.location.href;
    return  '<a href="' + url + '">-' + title + "</a>\n"; 
})()

/* URL + Title */
(() => { 
    const title = document.title;
    const url = document.location.href;
    return  url + ' : ' + title + "\n"; 
})()

/* URL + PageText (no breaks) */
(() => { 
    function stripLB(txt){
        return txt.replace(/(?:\r\n|\r|\n)/gm, ' ');
    }
    const url = document.location.href;
    const txt = document.body.innerText;
    return url + " : " + stripLB(txt) + "\n"; 
})()

/* URL + 1st paragraph (no breaks) */
(() => { 
    function stripLB(txt){
        return txt.replace(/(?:\r\n|\r|\n)/gm, ' ');
    }
    const url = document.location.href;
    const node = document.querySelector('p');
    let out = url + " : ";
    if(node){
        out += stripLB(node.innerText);
    }else{
        out += 'no paragraphs found';
    }
    return out + "\n";
})()

/* URL + Base64(URL) */
(() => {
    const url = document.location.href;
    return url + ": " + btoa(
        Array.from(
            (new TextEncoder).encode(url),
            (url => String.fromCodePoint(url))
        ).join('')
    ) + "\n"
})()

/* URL + LINK.text + LINK.href */
(() => { 
    function stripLB(txt){
        return txt.replace(/(?:\r\n|\r|\n)/gm, ' ');
    }
    const node = document.querySelector('a');
    const url = document.location.href;

    let out = url + " : ";
    if(node){
        out += stripLB(node.innerText) + " : " + node.href;
    }else {
        out += 'node not found';
    }
    out += "\n";

    return out;
})()

/* Markdown Link */
(() => {
    const title = document.title;
    const url = document.location.href;
    return '[' + title.replace(/\]/g, '\\]') + '](' + url + ')\n';
})()

/* URL + Meta Description */
(() => {
    const url = document.location.href;
    const meta = document.querySelector('meta[name="description"]');
    const desc = meta ? meta.content.trim() : 'no description found';
    return url + ' : ' + desc + '\n';
})()

/* CSV Row: "Title","URL" */
(() => {
    function esc(s) { return '"' + String(s).replace(/"/g, '""') + '"'; }
    const title = document.title;
    const url = document.location.href;
    return esc(title) + ',' + esc(url) + '\n';
})()

/* JSON: {title, url} */
(() => {
    const title = document.title;
    const url = document.location.href;
    return JSON.stringify({ title, url }) + '\n';
})()

/* URL + All Page Links (deduped) */
(() => {
    const url = document.location.href;
    const links = Array.from(document.querySelectorAll('a[href]'))
        .map((a) => a.href)
        .filter((v, i, arr) => arr.indexOf(v) === i);
    let out = url + ' (' + links.length + ' links):\n';
    links.forEach((l) => { out += '  ' + l + '\n'; });
    return out;
})()

/* URL + Selected Text */
(() => {
    const url = document.location.href;
    const sel = document.getSelection().toString().trim();
    return url + ' : ' + (sel !== '' ? sel : '(nothing selected)') + '\n';
})()

/* URL + Canonical Link */
(() => {
    const url = document.location.href;
    const link = document.querySelector('link[rel="canonical"]');
    return url + ' -> canonical: ' + (link ? link.href : 'none found') + '\n';
})()

/* URL + Word Count */
(() => {
    const url = document.location.href;
    const txt = document.body.innerText || '';
    const words = txt.trim().split(/\s+/).filter(Boolean).length;
    return url + ' : ' + words + ' words\n';
})()

/* URL + Open Graph Image */
(() => {
    const url = document.location.href;
    const meta = document.querySelector('meta[property="og:image"]');
    return url + ' : ' + (meta ? meta.content : 'no og:image found') + '\n';
})()
